use super::super::{EndpointDoc, body_param, ep, path_param, query_param};
use serde_json::{Value, json};

fn goal_example() -> Value {
    json!({
        "objective": "Inspect current repository health and independently verify the findings.",
        "success": ["Fresh observations and independently checked artifacts support the result."],
        "constraints": ["Read-only discovery; preserve existing work and unknown outcomes."],
        "repo": "kunkunGames/AgentDesk", "planner": "coder", "verifier": "qa",
        "agents": ["coder", "qa"],
        "budget": {"max_dispatches": 10, "max_elapsed_secs": 1800,
                   "node_timeout_secs": 600, "max_evolutions": 2,
                   "max_observed_tool_calls": 100}
    })
}

